#pragma once

/*
* Runtime support for the headers generated by UEVRBridgeGen.
*
* The generator copies this file next to the generated headers on every run.
* Edit the copy in tools/UEVRBridgeGen/Resources, not the one in the output folder.
*
* Every property and function is resolved by name through the UEVR API on first use
* and cached. Nothing here depends on the memory layout of a Blueprint class, so
* editing a Blueprint never requires a new dump. A name that cannot be resolved
* logs an error and throws std::runtime_error.
*
* The caches hold raw pointers into the Unreal object array. When the engine unloads a
* Blueprint class and loads it again, for example at a level change or after a pak hot
* reload, those pointers and offsets are stale. bridge::invalidate() marks every cache
* as stale at once; each one resolves again on its next use.
*/

#include <cstdint>
#include <cstring>
#include <cwctype>
#include <initializer_list>
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

#include "@UEVR_API_INCLUDE@"

namespace bridge
{
using API = uevr::API;

// FName comparison in Unreal ignores case, and the cooked game may store a different
// casing than the editor (for example "beam" versus "Beam"). Lookups below match the
// way Unreal does.
inline bool iequals(std::wstring_view a, std::wstring_view b)
{
    if (a.size() != b.size()) {
        return false;
    }
    for (size_t i = 0; i < a.size(); ++i) {
        if (std::towlower(a[i]) != std::towlower(b[i])) {
            return false;
        }
    }
    return true;
}

// Property declared on this struct only. Exact match first, then case-insensitive.
inline API::FProperty* find_property_ci(API::UStruct* owner, const wchar_t* name)
{
    if (API::FProperty* exact = owner->find_property(name)) {
        return exact;
    }
    for (API::FField* field = owner->get_child_properties(); field != nullptr; field = field->get_next()) {
        if (iequals(field->get_fname()->to_string(), name)) {
            return (API::FProperty*)field;
        }
    }
    return nullptr;
}

// Function declared on this struct only. Exact match first, then case-insensitive.
inline API::UFunction* find_function_ci(API::UStruct* owner, const wchar_t* name)
{
    if (API::UFunction* exact = owner->find_function(name)) {
        return exact;
    }
    for (API::UField* child = owner->get_children(); child != nullptr; child = child->get_next()) {
        if (child->is_a(API::UFunction::static_class()) && iequals(child->get_fname()->to_string(), name)) {
            return (API::UFunction*)child;
        }
    }
    return nullptr;
}

// The UEVR log takes char. Object paths and member names are ASCII in practice;
// anything else becomes '?'.
inline std::string narrow(std::wstring_view wide)
{
    std::string out;
    out.reserve(wide.size());
    for (const wchar_t c : wide) {
        out.push_back(c < 128 ? static_cast<char>(c) : '?');
    }
    return out;
}

[[noreturn]] inline void fail(const std::wstring& message)
{
    const std::string text = narrow(message);
    API::get()->log_error("[bridge] %s", text.c_str());
    throw std::runtime_error(text);
}

inline API::UObject* as_uobject(const void* object)
{
    return (API::UObject*)object;
}

inline int32_t align_up(int32_t value, int32_t alignment)
{
    alignment = alignment > 0 ? alignment : 1;
    return (value + alignment - 1) / alignment * alignment;
}

// Size of one struct instance, as TArray<Struct> lays them out.
inline int32_t struct_size(API::UScriptStruct* script_struct)
{
    return align_up(script_struct->get_properties_size(), script_struct->get_min_alignment());
}

// Counts the calls to invalidate(). Every cache remembers the value it resolved under
// and resolves again when the value has moved on.
inline uint32_t& generation()
{
    static uint32_t value = 1;
    return value;
}

// Marks every cached class, struct, property and function as stale. Call it when the
// engine may have unloaded and reloaded Blueprint classes, before anything resolves
// against them. The next use of each cache pays one lookup again.
inline void invalidate()
{
    ++generation();
    API::get()->log_warn("[bridge] caches invalidated, generation %u", generation());
}

// Paths of the classes and structs the last warm-up found not loaded. warm_begin()
// clears the list; the caller of BridgeWarmupAll() reads it afterwards to see what is
// still missing. ObjectRef::get() removes a path once the object resolves on first use.
inline std::vector<std::wstring>& warm_skipped_paths()
{
    static std::vector<std::wstring> paths;
    return paths;
}

// True while a warm-up runs. ObjectRef::get() stays quiet for lookups made by the warm-up
// and logs every lookup made outside it, so the log shows which classes resolve lazily.
inline bool& warm_in_progress()
{
    static bool in_progress = false;
    return in_progress;
}

// Call before the warm-up so warm_skipped_paths() describes this run only.
inline void warm_begin()
{
    warm_skipped_paths().clear();
    warm_in_progress() = true;
}

// Call after the warm-up, also when it threw.
inline void warm_end()
{
    warm_in_progress() = false;
}

// Called when a warm-up finds its class or struct not loaded yet. Nothing is cached in
// that case, so the names resolve on first use as usual. Logged at warn level because
// UEVR does not write plugin info messages to its log file.
inline void warm_skipped(const wchar_t* path)
{
    warm_skipped_paths().emplace_back(path);
    API::get()->log_warn("[bridge] warm-up skipped, not loaded: %s", narrow(path).c_str());
}

// Called when an object resolves outside the warm-up, on first use. Tells apart a class
// the last warm-up skipped because it was not loaded from a class the warm-up never tried,
// so the second message points at a class missing from the plugin's warm-up list.
inline void warm_resolved_late(const wchar_t* path)
{
    if (warm_in_progress()) {
        return;
    }
    std::vector<std::wstring>& paths = warm_skipped_paths();
    for (auto it = paths.begin(); it != paths.end(); ++it) {
        if (*it == path) {
            paths.erase(it);
            API::get()->log_warn("[bridge] loaded on first use, after warm-up skipped it: %s", narrow(path).c_str());
            return;
        }
    }
    API::get()->log_warn("[bridge] resolved on first use, not pre-warmed: %s", narrow(path).c_str());
}

// Finds a UObject by its full search path on first use and keeps it.
// A miss is not cached, so a class that loads later is still found.
template <class T>
struct ObjectRef
{
    const wchar_t* path;
    T* cached{nullptr};
    uint32_t resolved_in{0};

    T* get()
    {
        if (cached == nullptr || resolved_in != generation()) {
            cached = API::get()->find_uobject<T>(path);
            resolved_in = generation();
            if (cached != nullptr) {
                warm_resolved_late(path);
            }
        }
        return cached;
    }

    T* require()
    {
        T* result = get();
        if (result == nullptr) {
            fail(L"object not found: " + std::wstring(path));
        }
        return result;
    }
};

using ClassRef = ObjectRef<API::UClass>;
using StructRef = ObjectRef<API::UScriptStruct>;

// One reflected property, resolved by name on first use against the struct that declares it.
struct Prop
{
    const wchar_t* name;
    API::FProperty* prop{nullptr};
    int32_t offset{-1};
    uint32_t resolved_in{0};

    API::FProperty* resolve(API::UStruct* owner)
    {
        if (prop == nullptr || resolved_in != generation()) {
            if (owner == nullptr) {
                fail(L"null owner for property " + std::wstring(name));
            }
            prop = nullptr;
            for (API::UStruct* s = owner; s != nullptr && prop == nullptr; s = s->get_super_struct()) {
                prop = find_property_ci(s, name);
            }
            if (prop == nullptr) {
                fail(L"property not found: " + std::wstring(name));
            }
            offset = prop->get_offset();
            resolved_in = generation();
        }
        return prop;
    }

    uint8_t* address(void* base, API::UStruct* owner)
    {
        resolve(owner);
        return (uint8_t*)base + offset;
    }

    template <class T>
    T& ref(void* base, API::UStruct* owner)
    {
        return *reinterpret_cast<T*>(address(base, owner));
    }

    bool get_bool(void* base, API::UStruct* owner)
    {
        return ((API::FBoolProperty*)resolve(owner))->get_value_from_propbase(address(base, owner));
    }

    void set_bool(void* base, API::UStruct* owner, bool value)
    {
        ((API::FBoolProperty*)resolve(owner))->set_value_in_propbase(address(base, owner), value);
    }
};

// One Blueprint function plus the parameters the generated wrapper passes.
// Resolved against the target object's own class, so Blueprint overrides are honoured.
struct Func
{
    const wchar_t* name;
    std::vector<const wchar_t*> param_names;

    API::UClass* resolved_for{nullptr};
    API::UFunction* function{nullptr};
    std::vector<API::FProperty*> props;
    std::vector<int32_t> offsets;
    int32_t size{0};
    uint32_t resolved_in{0};

    void resolve(API::UClass* cls)
    {
        if (cls == nullptr) {
            fail(L"null class for function " + std::wstring(name));
        }
        if (cls == resolved_for && function != nullptr && resolved_in == generation()) {
            return;
        }
        function = find_in_hierarchy(cls);
        if (function == nullptr) {
            fail(L"function not found: " + std::wstring(name));
        }
        resolve_params();
        size = align_up(function->get_properties_size(), 16);
        resolved_for = cls;
        resolved_in = generation();
    }

private:
    API::UFunction* find_in_hierarchy(API::UClass* cls) const
    {
        for (API::UStruct* s = cls; s != nullptr; s = s->get_super_struct()) {
            if (API::UFunction* found = find_function_ci(s, name)) {
                return found;
            }
        }
        return nullptr;
    }

    void resolve_params()
    {
        props.clear();
        offsets.clear();
        for (const wchar_t* param : param_names) {
            API::FProperty* prop = find_property_ci(function, param);
            if (prop == nullptr) {
                fail(L"parameter not found: " + std::wstring(name) + L"." + param);
            }
            props.push_back(prop);
            offsets.push_back(prop->get_offset());
        }
    }
};

// Warm-up. Resolves properties or functions ahead of their first use, so no call site
// pays the name lookup in the middle of a frame. A name that does not resolve is logged
// by fail() and reported through the return value; the remaining names are still tried.
inline bool warm(API::UStruct* owner, std::initializer_list<Prop*> props)
{
    bool ok = true;
    for (Prop* prop : props) {
        try {
            prop->resolve(owner);
        } catch (const std::runtime_error&) {
            ok = false;
        }
    }
    return ok;
}

inline bool warm(API::UClass* cls, std::initializer_list<Func*> funcs)
{
    bool ok = true;
    for (Func* func : funcs) {
        try {
            func->resolve(cls);
        } catch (const std::runtime_error&) {
            ok = false;
        }
    }
    return ok;
}

// A zeroed parameter buffer for one call. Lives on the stack unless the function's
// parameters exceed the inline capacity.
class Call
{
public:
    Call(Func& func, API::UObject* target)
        : m_func(func), m_target(target)
    {
        if (target == nullptr) {
            fail(L"null target for function " + std::wstring(func.name));
        }
        func.resolve(target->get_class());
        if (func.size > (int32_t)sizeof(m_inline)) {
            m_heap.assign(func.size, 0);
            m_data = m_heap.data();
        } else {
            std::memset(m_inline, 0, sizeof(m_inline));
            m_data = m_inline;
        }
    }

    Call(const Call&) = delete;
    Call& operator=(const Call&) = delete;

    template <class T>
    void set(size_t index, const T& value)
    {
        std::memcpy(slot(index), &value, sizeof(T));
    }

    template <class T>
    T get(size_t index) const
    {
        T value{};
        std::memcpy(&value, slot(index), sizeof(T));
        return value;
    }

    void set_bool(size_t index, bool value)
    {
        ((API::FBoolProperty*)m_func.props[index])->set_value_in_propbase(slot(index), value);
    }

    bool get_bool(size_t index) const
    {
        return ((API::FBoolProperty*)m_func.props[index])->get_value_from_propbase(slot(index));
    }

    void set_raw(size_t index, const void* source, size_t bytes)
    {
        if (source != nullptr) {
            std::memcpy(slot(index), source, bytes);
        }
    }

    void copy_out(size_t index, void* destination, size_t bytes) const
    {
        if (destination != nullptr) {
            std::memcpy(destination, slot(index), bytes);
        }
    }

    void invoke()
    {
        m_target->process_event(m_func.function, m_data);
    }

private:
    uint8_t* slot(size_t index) const
    {
        return m_data + m_func.offsets[index];
    }

    Func& m_func;
    API::UObject* m_target;
    alignas(16) uint8_t m_inline[512];
    std::vector<uint8_t> m_heap;
    uint8_t* m_data{nullptr};
};

// View over a TArray whose element is a User Defined Struct. Same layout as TArray.
template <class View>
struct StructArray
{
    uint8_t* Data;
    int32_t Num;
    int32_t Max;

    int32_t size() const { return Num; }

    View operator[](int32_t index) const
    {
        return View{ Data + (size_t)index * View::StaticSize() };
    }
};

// Owns the bytes of one User Defined Struct returned from a Blueprint function.
template <class View>
class Boxed
{
public:
    explicit Boxed(int32_t bytes)
        : m_bytes((size_t)bytes, 0)
    {
    }

    View view() { return View{ m_bytes.data() }; }
    View operator*() { return view(); }
    uint8_t* data() { return m_bytes.data(); }
    size_t size() const { return m_bytes.size(); }

private:
    std::vector<uint8_t> m_bytes;
};
}
